def build_batch_copy_payload(pack_id: str = "pack_celebrity_story") -> Dict[str, Any]:
    pack = CURATED_BATCH_PACKS.get(pack_id) or CURATED_BATCH_PACKS["pack_celebrity_story"]
    stories = pack["stories"]
    separator = "\n\n--------------------------------------------------\n\n"
    copy_block_text = separator.join([s["draft_121"].strip() for s in stories])

    topic_index = [
        {
            "order": idx + 1,
            "title": s["title"],
            "detail": s["detail"],
            "cover_line1": s["cover_line1"],
            "cover_line2": s["cover_line2"],
        }
        for idx, s in enumerate(stories)
    ]

    return {
        "pack_id": pack["id"],
        "pack_name": pack["name"],
        "count": len(stories),
        "copy_block_text": copy_block_text,
        "topic_index": topic_index,
        "available_packs": [
            {"id": k, "name": v["name"], "count": len(v["stories"])}
            for k, v in CURATED_BATCH_PACKS.items()
        ],
    }
